INSERT INTO `competition` (`id`, `name`, `level`, `category`, `start_time`, `end_time`, `competition_start`, `competition_end`, `max_team_size`, `cover_url`, `source_url`, `content`, `organizer`, `tags`, `tracks`, `status`, `create_time`, `update_time`) VALUES (1,'第十届“互联网+”大学生创新创业大赛','国家级','A','2026-05-01 00:00:00','2026-06-30 00:00:00','2026-07-10 00:00:00','2026-07-15 00:00:00',5,'http://tfnb602dp.hn-bkt.clouddn.com/uploads/1779896823971_6epzzmr3.png',NULL,'updated by automated API smoke test','教育部高等教育司','[\"创新创业\",\"双创\",\"商业计划\"]',NULL,'published','2026-05-26 01:27:36','2026-05-28 16:09:01'),(2,'2026年全国大学生电子设计竞赛','国家级','B','2026-06-01 00:00:00','2026-07-20 23:59:59','2026-08-01 08:00:00','2026-08-04 20:00:00',3,'https://img.example.com/nuedc.jpg',NULL,'<p>全国大学生电子设计竞赛是教育部倡导的大学生重要学科竞赛，重在考查硬件设计、模拟电路、数字系统与单片机编程等综合水平。</p>','教育部高等教育司、工业和信息化部人事教育司','[\"电子设计\",\"硬件\",\"单片机\",\"PCB\"]',NULL,'published','2026-05-26 01:27:36','2026-05-27 01:20:51'),(3,'第十七届蓝桥杯全国软件和信息技术专业人才大赛','国家级','A','2026-09-01 00:00:00','2026-11-30 23:59:59','2026-12-15 09:00:00','2026-12-15 13:00:00',1,'https://img.example.com/lanqiao.jpg',NULL,'<p>蓝桥杯全国软件和信息技术专业人才大赛是国内极具影响力的软件类个人程序设计大赛，涵盖Java、C++、Python及Web开发等多赛道。</p>','工业和信息化部人才交流中心','[\"程序设计\",\"算法\",\"Java\",\"C++\",\"Python\"]',NULL,'published','2026-05-26 01:27:36','2026-05-27 01:20:51'),(4,'2026年高教社杯全国大学生数学建模竞赛','国家级','B','2026-08-01 00:00:00','2026-09-05 20:00:00','2026-09-10 18:00:00','2026-09-13 20:00:00',3,'https://img.example.com/mcm.jpg',NULL,'<p>全国大学生数学建模竞赛是考察学生数学建模、计算机编程以及学术论文写作综合能力的经典三人组队赛事。</p>','中国工业与应用数学学会','[\"数学建模\",\"MATLAB\",\"Python\",\"学术写作\"]',NULL,'published','2026-05-26 01:27:36','2026-05-27 01:20:51'),(5,'第四届全国大学生艺术设计大奖赛','国家级','C','2026-04-15 00:00:00','2026-06-15 23:59:59','2026-06-25 09:00:00','2026-06-28 18:00:00',3,'https://img.example.com/design_art.jpg',NULL,'<p>为优秀设计学子提供展现视觉传达、工业造型、数字化多媒体艺术水平的高水平创新设计竞赛。</p>','中国艺术设计联合会','[\"艺术设计\",\"UI\",\"视觉\",\"3D建模\"]',NULL,'published','2026-05-26 01:27:36','2026-05-27 01:20:51');
